                </div>
                <div class="worship-tabs" role="tablist"><button type="button" role="tab" aria-selected="true" data-room-tab="chat">Chat</button><button type="button" role="tab" aria-selected="false" data-room-tab="polls">Polls</button><button type="button" role="tab" aria-selected="false" data-room-tab="prayer">Prayer</button></div>
