                <section data-room-panel="prayer" class="worship-tab-panel" hidden>
                    <p class="worship-form-note">Share only what you are comfortable submitting. Your request goes to the ministry’s authorized care team.</p>
                    <form class="worship-prayer-form" data-prayer-form><input name="display_name" maxlength="160" placeholder="Name (optional)"><input name="contact_email" type="email" maxlength="254" placeholder="Email (optional)"><textarea name="prayer_text" maxlength="4000" placeholder="How can we pray with you?" required></textarea><label class="worship-consent"><input type="checkbox" name="consent_to_contact"> I welcome a response from the care team.</label><button class="button" type="submit">Send prayer request</button></form><p class="worship-form-note" data-prayer-note></p>
                </section>
                <section class="worship-response-sheet" data-response-sheet hidden><div><button type="button" class="worship-sheet-close" data-response-close aria-label="Close">×</button><p>CONNECT</p><h3 data-response-title>We’re glad you’re here</h3><form data-response-form><input name="name" maxlength="160" placeholder="Your name"><input name="email" type="email" maxlength="254" placeholder="Email address"><input name="phone" maxlength="40" placeholder="Phone (optional)"><label class="worship-consent"><input type="checkbox" name="consent_to_contact" checked> I agree to be contacted about this request.</label><button class="button" type="submit">Send request</button></form><p class="worship-form-note" data-response-note></p></div></section>
            @else
                <div class="worship-incident"><span aria-hidden="true">!</span><div><strong>We are working on the broadcast.</strong><p>Connection and prayer options will return when the service is restored.</p></div></div>
                <a class="button public-action" href="{{ route('public.events') }}">Explore upcoming events</a>
            @endif
        </aside>
    </section>

    <script>
        (() => {
            const room = document.querySelector('[data-service-room]'); if (!room) return;
            const api = room.dataset.apiBase; const live = room.dataset.live === 'true';
            const keyName = `ministry-service-guest-${api.split('/').pop()}`;
            let guestKey = localStorage.getItem(keyName); if (!guestKey) { guestKey = crypto.randomUUID?.() + crypto.randomUUID?.() || `${Date.now()}-${Math.random()}-${Math.random()}`; localStorage.setItem(keyName, guestKey); }
            const request = async (path, options = {}) => { const response = await fetch(`${api}${path}`, {headers: {'Accept':'application/json', 'Content-Type':'application/json', ...(options.headers || {})}, ...options}); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.message || 'That action could not be completed. Please try again.'); return body; };
            const safeText = (value) => document.createTextNode(value ?? '');
            const note = (target, message, error = false) => { if (!target) return; target.textContent = message; target.classList.toggle('is-error', error); };
            const showTab = (name) => { room.querySelectorAll('[data-room-tab]').forEach((button) => button.setAttribute('aria-selected', String(button.dataset.roomTab === name))); room.querySelectorAll('[data-room-panel]').forEach((panel) => panel.hidden = panel.dataset.roomPanel !== name); };
            room.querySelectorAll('[data-room-tab]').forEach((button) => button.addEventListener('click', () => showTab(button.dataset.roomTab)));
            room.querySelector('[data-low-bandwidth]')?.addEventListener('click', (event) => { const player = room.querySelector('[data-primary-player]'); if (!player) return; player.src = event.currentTarget.dataset.url; player.play().catch(() => {}); event.currentTarget.textContent = 'Lower-bandwidth playback active'; event.currentTarget.disabled = true; });
            if (!live) return;
            const renderChat = (messages, meta) => { const feed = room.querySelector('[data-chat-feed]'); if (!feed) return; feed.replaceChildren(); if (meta?.paused) { const paused = document.createElement('p'); paused.className = 'worship-chat-paused'; paused.append(safeText('Chat is temporarily paused by the host.')); feed.append(paused); } if (!messages.length) { const empty = document.createElement('p'); empty.className = 'worship-loading'; empty.append(safeText('Be the first to welcome someone.')); feed.append(empty); return; } messages.forEach((message) => { const item = document.createElement('article'); const name = document.createElement('strong'); name.append(safeText(message.display_name)); const content = document.createElement('p'); content.append(safeText(message.content)); if (message.is_host) { const host = document.createElement('span'); host.className = 'worship-host-tag'; host.append(safeText('Host')); name.append(host); } item.append(name, content); feed.append(item); }); feed.scrollTop = feed.scrollHeight; };
            const refreshChat = async () => { try { const payload = await request('/chat'); renderChat(payload.data || [], payload.meta); } catch (error) { note(room.querySelector('[data-chat-note]'), error.message, true); } };
            const renderPolls = (polls) => { const host = room.querySelector('[data-polls]'); if (!host) return; host.replaceChildren(); const open = (polls || []).filter((poll) => poll.status === 'open'); if (!open.length) { const empty = document.createElement('p'); empty.className = 'worship-loading'; empty.append(safeText('No poll is open right now.')); host.append(empty); return; } open.forEach((poll) => { const form = document.createElement('form'); form.className = 'worship-poll'; const title = document.createElement('strong'); title.append(safeText(poll.question)); form.append(title); poll.options.forEach((option) => { const label = document.createElement('label'); const input = document.createElement('input'); input.type = 'radio'; input.name = `poll-${poll.id}`; input.value = option.id; label.append(input, safeText(option.label)); form.append(label); }); const submit = document.createElement('button'); submit.type = 'submit'; submit.className = 'button button-secondary'; submit.append(safeText('Submit response')); form.append(submit); form.addEventListener('submit', async (event) => { event.preventDefault(); const option = new FormData(form).get(`poll-${poll.id}`); if (!option) return; try { await request(`/polls/${poll.id}/responses`, {method:'POST', body:JSON.stringify({option_id:option, guest_key:guestKey})}); submit.textContent = 'Response received'; submit.disabled = true; } catch (error) { submit.textContent = error.message; } }); host.append(form); }); };
            const refreshPolls = async () => { try { const payload = await request('/polls'); renderPolls(payload.data); } catch (_) {} };
            room.querySelector('[data-chat-form]')?.addEventListener('submit', async (event) => { event.preventDefault(); const form = event.currentTarget; const button = form.querySelector('button'); try { button.disabled = true; await request('/chat', {method:'POST', body:JSON.stringify({display_name: form.display_name.value, content: form.content.value, guest_key:guestKey})}); form.content.value = ''; note(room.querySelector('[data-chat-note]'), 'Message sent.'); await refreshChat(); } catch (error) { note(room.querySelector('[data-chat-note]'), error.message, true); } finally { button.disabled = false; } });
            room.querySelector('[data-prayer-form]')?.addEventListener('submit', async (event) => { event.preventDefault(); const form = event.currentTarget; const button = form.querySelector('button'); try { button.disabled = true; await request('/prayer-requests', {method:'POST', headers:{'Idempotency-Key': crypto.randomUUID?.() || String(Date.now())}, body:JSON.stringify({display_name:form.display_name.value || null, contact_email:form.contact_email.value || null, prayer_text:form.prayer_text.value, consent_to_contact:form.consent_to_contact.checked})}); form.reset(); note(room.querySelector('[data-prayer-note]'), 'Your prayer request has been received.'); } catch (error) { note(room.querySelector('[data-prayer-note]'), error.message, true); } finally { button.disabled = false; } });
            const sheet = room.querySelector('[data-response-sheet]'); let responseKind = 'newcomer'; const labels = {newcomer:'We’re glad you’re here', speak_to_someone:'Speak with someone', join_department:'Find your department'}; room.querySelectorAll('[data-response-kind]').forEach((button) => button.addEventListener('click', () => { responseKind = button.dataset.responseKind; sheet.querySelector('[data-response-title]').textContent = labels[responseKind]; sheet.hidden = false; sheet.querySelector('input[name=name]')?.focus(); })); room.querySelector('[data-response-close]')?.addEventListener('click', () => sheet.hidden = true); sheet?.addEventListener('click', (event) => { if (event.target === sheet) sheet.hidden = true; }); room.querySelector('[data-response-form]')?.addEventListener('submit', async (event) => { event.preventDefault(); const form = event.currentTarget; const button = form.querySelector('button'); try { button.disabled = true; await request('/responses', {method:'POST', headers:{'Idempotency-Key': crypto.randomUUID?.() || String(Date.now())}, body:JSON.stringify({kind:responseKind, name:form.name.value || null, email:form.email.value || null, phone:form.phone.value || null, consent_to_contact:form.consent_to_contact.checked})}); form.reset(); note(room.querySelector('[data-response-note]'), 'Thank you. Your request has been received.'); } catch (error) { note(room.querySelector('[data-response-note]'), error.message, true); } finally { button.disabled = false; } });
            refreshChat(); refreshPolls(); window.setInterval(() => { refreshChat(); refreshPolls(); }, 10000);
        })();
    </script>
</x-layouts.worship>

